from pathlib import Path
import re, html, base64, json, hashlib
root=Path(__file__).resolve().parents[5]
base=root/"02-PROJECTS/TileScape/游戏逻辑"
src=base/"需求-道具礼包BannerUI美术.md"
out=base/"TS_Prop_Banner_Art.html"
assets=base/"assets/prop-banner-art"
assets.mkdir(exist_ok=True)
text=src.read_text(encoding="utf-8-sig")
body=re.sub(r"\A---\n.*?\n---\n","",text,flags=re.S)
body=re.sub(r"^# .*\n","",body,count=1,flags=re.M)
def inline(s):
    s=html.escape(s)
    s=re.sub(r"\[\[([^|\]]+)\|([^\]]+)\]\]",lambda m:'<a href="'+html.escape(str(Path("../../..")/(m[1]+("" if "." in Path(m[1]).name else ".md"))).replace("\\","/"))+'">'+m[2]+"</a>",s)
    s=re.sub(r"\*\*(.+?)\*\*",r"<strong>\1</strong>",s)
    return s
lines=body.splitlines()
parts=[];nav=[];i=0;num=0
while i<len(lines):
    line=lines[i]
    if not line.strip():i+=1;continue
    if line.startswith("## "):
        num+=1
        title=re.sub(r"^\d+\.\s*","",line[3:])
        nav.append((num,title))
        parts.append(f'<h2 id="s{num}"><span>{num:02d}</span>{html.escape(title)}</h2>')
        i+=1
    elif line.startswith("|"):
        rows=[]
        while i<len(lines) and lines[i].startswith("|"):
            cells=[c.strip() for c in lines[i].strip("|").split("|")];i+=1
            if all(re.match(r"^:?-+:?$",c) for c in cells):continue
            rows.append(cells)
        parts.append('<div class="table-scroll"><table><thead><tr>'+''.join("<th>"+inline(c)+"</th>" for c in rows[0])+"</tr></thead><tbody>"+''.join("<tr>"+''.join("<td>"+inline(c)+"</td>" for c in row)+"</tr>" for row in rows[1:])+"</tbody></table></div>")
    elif re.match(r"^\d+\. ",line):
        li=[]
        while i<len(lines) and re.match(r"^\d+\. ",lines[i]):
            li.append("<li>"+inline(re.sub(r"^\d+\. ","",lines[i]))+"</li>");i+=1
        parts.append("<ol>"+"".join(li)+"</ol>")
    else:
        para=[]
        while i<len(lines) and lines[i].strip() and not lines[i].startswith(("## ","|")):
            para.append(lines[i]);i+=1
        parts.append("<p>"+inline(" ".join(para))+"</p>")
