hero=r"""<section class="hero" id="preview"><div class="herohead"><h2>TS 商城样式 · 道具礼包示意</h2><small>1080 × 550 · 非最终美术稿</small></div><div class="tabs" role="tablist" aria-label="切换主道具"></div><div class="stylebar"><label for="skin">TS样式对照</label><select id="skin"><option value="standard">普通礼包 · 奶油 / 红</option><option value="promo">顶部促销 · 蓝 / 橙</option></select></div><div class="stage"><div class="banner"><div class="inner"><div class="rewards"><div class="mainprop"><img id="mainIcon" alt=""><span class="qty">×N</span></div><div class="currency"><svg viewBox="0 0 120 100" role="img" aria-label="TS金币形象结构占位"><g fill="#ffd044" stroke="#d99410" stroke-width="3"><ellipse cx="35" cy="76" rx="24" ry="12"/><ellipse cx="35" cy="68" rx="24" ry="12"/><ellipse cx="87" cy="76" rx="23" ry="12"/><ellipse cx="87" cy="68" rx="23" ry="12"/><ellipse cx="60" cy="55" rx="28" ry="14"/><ellipse cx="60" cy="46" rx="28" ry="14"/><ellipse cx="60" cy="37" rx="28" ry="14"/><circle cx="64" cy="70" r="23"/></g><circle cx="64" cy="70" r="17" fill="#ffdc50" stroke="#fff298" stroke-width="2"/><path d="m64 56 4 9 10 1-8 7 2 10-8-5-9 5 2-10-7-7 10-1Z" fill="#ffef97" stroke="#e4a51c" stroke-width="1.5"/></svg><span class="qty">N</span><small>金币图形仅作占位</small></div><div class="extras" id="extras"></div></div><div class="footer"><span class="packname" id="packname"></span><div class="buy" aria-label="价格占位，不可支付">价格</div></div></div><span class="marker m1">1</span><span class="marker m2">2</span><span class="marker m3">3</span><span class="marker m4">4</span><span class="marker m5">5</span></div></div><div class="herofoot"><label><input type="checkbox" id="marks" checked> 显示分区编号</label><div class="legend"><div><b>1 目标道具</b>　大图标＋合计数量</div><div><b>2 购买货币</b>　TS 金币形象，资源待替换</div><div><b>3 其他三种道具</b>　上二、下一</div><div><b>4 礼包名称</b>　独立文本，可本地化</div><div><b>5 价格按钮</b>　绿色，动态价格</div><div><b>共同底板</b>　TS 圆框／奖励底／彩色底栏</div></div>图标为 TS 现有资源；底板、字体和金币为网页布局示意。数量、价格及合并数量规则仍待确认。</div></section>"""
js=r"""
const icons=ICONS;
const props=[{id:11,name:"撤回"},{id:14,name:"手套"},{id:13,name:"磁铁"},{id:12,name:"风车"}];
const tabs=document.querySelector(".tabs");
function select(id){const p=props.find(p=>p.id===id);document.getElementById("mainIcon").src=icons[id];document.getElementById("mainIcon").alt=p.name;document.getElementById("packname").textContent=p.name+"补给";document.getElementById("extras").innerHTML=props.filter(p=>p.id!==id).map(p=>'<div class="extra"><img src="'+icons[p.id]+'" alt="'+p.name+'"><span class="qty">×N</span></div>').join("");tabs.querySelectorAll("button").forEach(b=>b.setAttribute("aria-selected",String(Number(b.dataset.id)===id)));}
props.forEach(p=>{const b=document.createElement("button");b.type="button";b.role="tab";b.dataset.id=p.id;b.textContent=p.name;b.onclick=()=>select(p.id);tabs.appendChild(b)});
document.getElementById("marks").onchange=e=>document.querySelector(".banner").classList.toggle("marks-off",!e.target.checked);
document.getElementById("skin").onchange=e=>document.querySelector(".banner").classList.toggle("promo",e.target.value==="promo");
select(14);
""".replace("ICONS",json.dumps(icons))
